def decisions(a, k):
    s = SLOTS[a]; E = lambda key: s[key][0]; D = lambda key: s[key][1]
    n = s["n"]
    if k == "500":
        return {
          "silhouette": T(f"The {n[0]} is composed as {E('c500')}; 1 m is 2 mm, so only the overall form is drawn, with a restrained closed outline and no internal structure.", f"Die {n[1]} ist als {D('c500')} komponiert; 1 m sind 2 mm, daher wird nur die Gesamtform mit zurückhaltendem geschlossenem Umriss und ohne innere Struktur gezeichnet."),
          "retained": T(f"Retained: {E('w500')}.", f"Beibehalten: {D('w500')}."),
          "merged": T(f"Merged into the crown path: {E('m500')}.", f"Im Kronenpfad vereint: {D('m500')}."),
          "omitted": T(f"Omitted: {E('t500')}; they are far below 0.1 mm line width at this scale.", f"Weggelassen: {D('t500')}; sie liegen bei diesem Maßstab weit unter 0,1 mm Strichbreite."),
          "thinElements": T(f"Thin parts ({E('t500')}) are not thickened; they are merged into the filled mass or dropped, so the outline stays within the real outline tolerance of the 1:50 drawing.", f"Dünne Teile ({D('t500')}) werden nicht verdickt, sondern in die gefüllte Masse eingeschmolzen oder weggelassen, so dass der Umriss innerhalb der realen Umrisstoleranz der 1:50-Zeichnung bleibt."),
          "hatching": T("No hatching; the pen is 0.15 mm for outlines and 0.25 mm for the ground line.", "Keine Schraffur; der Stift ist 0,15 mm für Umrisse und 0,25 mm für die Bodenlinie."),
          "styles": T("Light line: closed outline only. Dark solid: the crown path reads as one dark mass, the bole lighter. Both stay readable at 36 mm printed height or less.", "Helle Linie: nur der geschlossene Umriss. Dunkle Fläche: der Kronenpfad liest sich als eine dunkle Masse, der Schaft heller. Beides bleibt bei höchstens 36 mm gedruckter Höhe lesbar."),
          "overlays": T(f"Thermal and structural overlays map onto: {E('r500')}. Merged paths show the area-weighted value of their regions, labelled as merged.", f"Thermische und statische Überlagerungen bilden sich ab auf: {D('r500')}. Vereinte Pfade zeigen den flächengewichteten Wert ihrer Regionen, als vereint gekennzeichnet.")}
    if k == "200":
        return {
          "silhouette": T(f"At 1:200 (1 m is 5 mm) the {n[0]} is separated into its main masses: {E('m200')}.", f"Bei 1:200 (1 m sind 5 mm) wird die {D('n') if False else n[1]} in ihre Hauptmassen aufgeteilt: {D('m200')}."),
          "retained": T(f"Retained: {E('w200')}.", f"Beibehalten: {D('w200')}."),
          "merged": T("Neighbouring twigs, leaf clusters and bark relief are merged into their mass outlines.", "Benachbarte Zweige, Blattbüschel und Rindenrelief sind in die Massenumrisse eingeschmolzen."),
          "omitted": T(f"Omitted: {E('t500')} and all texture strokes; gaps below the minimum gap between separate outlines are closed by overlapping the masses.", f"Weggelassen: {D('t500')} und alle Texturstriche; Lücken unter dem Mindestabstand zwischen getrennten Umrissen werden durch Überlappen der Massen geschlossen."),
          "thinElements": T("Slender limbs and branches are drawn as tapered outlines at their real section width where this is at least 0.3 mm on paper, otherwise they stay as an under-layer hidden by the masses.", "Schlanke Äste und Zweige werden mit realer Querschnittsbreite als verjüngte Umrisse gezeichnet, wo diese auf dem Papier mindestens 0,3 mm beträgt, sonst bleiben sie als von den Massen verdeckte Unterlage."),
          "hatching": T(f"No hatching. Internal edges: {E('d200')}.", f"Keine Schraffur. Innere Kanten: {D('d200')}."),
          "styles": T("Light line: outlines 0.18 mm, one 0.13 mm detail pen. Dark solid: masses in tones separate sun and shade foliage, wood lighter.", "Helle Linie: Umrisse 0,18 mm, ein Detailstift 0,13 mm. Dunkle Fläche: Massen in Tonwerten trennen Sonnen- und Schattenlaub, Holz heller."),
          "overlays": T(f"Every thermal region keeps its own shape: {E('r500').split(' and, merged')[0]}; overlays follow the bone-bound masses, so sway and loads act on the drawn shapes.", f"Jede thermische Region behält ihre eigene Form: {D('r500').split(' sowie, im')[0]}; Überlagerungen folgen den knochengebundenen Massen, so dass Schwingung und Lasten an den gezeichneten Formen wirken.")}
    if k == "100":
        return {
          "silhouette": T(f"At 1:100 (1 m is 10 mm) the masses of 1:200 get finer lobes and the structure appears: {E('d100')}.", f"Bei 1:100 (1 m sind 10 mm) erhalten die Massen von 1:200 feinere Lappen und die Struktur erscheint: {D('d100')}."),
          "retained": T(f"Retained: {E('m200')}; {E('w200')}.", f"Beibehalten: {D('m200')}; {D('w200')}."),
          "merged": T("Single leaves and twig ends are merged into lobed foliage outlines; bark relief into a few fissure strokes.", "Einzelne Blätter und Zweigenden sind in gelappte Laubumrisse eingeschmolzen; Rindenrelief in wenige Risslinien."),
          "omitted": T("Omitted: individual leaves, fine twig tufts and knots; the fine 1:50 leaf marks are replaced by a few arcs.", "Weggelassen: einzelne Blätter, feine Zweigbüschel und Astknoten; die feinen 1:50-Blattzeichen sind durch wenige Bögen ersetzt."),
          "thinElements": T("Thin strokes are at least 0.1 mm; strands and fissures are drawn with the texture pen, branches at real section width.", "Dünne Striche sind mindestens 0,1 mm; Stränge und Risse mit dem Texturstift, Äste in realer Querschnittsbreite."),
          "hatching": T(f"Restrained: {E('h100')}. Hatch spacing is above the profile minimum.", f"Zurückhaltend: {D('h100')}. Der Schraffurabstand liegt über dem Profilminimum."),
          "styles": T("Light line: 0.2 mm outlines, 0.13 mm detail, 0.1 mm texture. Dark solid: tonal masses; detail strokes stay visible on them.", "Helle Linie: Umrisse 0,2 mm, Detail 0,13 mm, Textur 0,1 mm. Dunkle Fläche: getönte Massen; Detailstriche bleiben darauf sichtbar."),
          "overlays": T("Every region keeps its shape; the shade hatch (where present) is a pure drawing hatch and does not stand for temperature.", "Jede Region behält ihre Form; die Schattenschraffur (wo vorhanden) ist eine reine Zeichenschraffur und steht nicht für Temperatur.")}
    return {
          "silhouette": T(f"At 1:50 (1 m is 20 mm) the {n[0]} is drawn in full: {E('f50')}.", f"Bei 1:50 (1 m sind 20 mm) wird die {n[1]} vollständig gezeichnet: {D('f50')}."),
          "retained": T("Retained: every foliage mass, every woody member, texture and detail strokes as designed for this scale.", "Beibehalten: jede Laubmasse, jedes Holzglied, Textur- und Detailstriche wie für diesen Maßstab entworfen."),
          "merged": T("Only the clipped plug pieces at bone joints close the seams between tapered woody parts.", "Nur die Passstücke an den Knochengelenken schließen die Nähte zwischen verjüngten Holzteilen."),
          "omitted": T("Omitted: single leaves and bud scales, which are below 0.5 mm on paper.", "Weggelassen: einzelne Blätter und Knospenschuppen, die auf dem Papier unter 0,5 mm liegen."),
          "thinElements": T(f"{E('th50')}.", f"{D('th50')}."),
          "hatching": T("A thin 45 degree line hatch marks shaded foliage where the asset has a shade region; bark and leaves are otherwise drawn with strokes.", "Eine feine 45-Grad-Schraffur kennzeichnet beschattetes Laub, wo das Asset eine Schattenregion hat; Rinde und Blätter sind sonst mit Strichen gezeichnet."),
          "styles": T("Light line: 0.25 mm outlines, 0.18 mm detail, 0.13 mm texture. Dark solid: tonal fills separate bark, sun foliage and shade foliage.", "Helle Linie: Umrisse 0,25 mm, Detail 0,18 mm, Textur 0,13 mm. Dunkle Fläche: getönte Füllungen trennen Rinde, Sonnenlaub und Schattenlaub."),
          "overlays": T("Each thermal region has its own shapes; stroke details carry no region and follow their bone.", "Jede thermische Region hat eigene Formen; Strichdetails tragen keine Region und folgen ihrem Knochen.")}
